-- YourTaste marketplace core schema. Apply to a fresh Supabase PostgreSQL project.
-- Payment secrets must never be stored here. All monetary values are integer paise.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','vendor','admin');
create type public.vendor_status as enum ('pending','approved','rejected','suspended');
create type public.product_status as enum ('draft','pending_review','published','rejected','archived');
create type public.order_status as enum ('pending_payment','paid','processing','partially_shipped','shipped','delivered','cancelled','refund_pending','refunded');
create type public.payment_status as enum ('created','authorized','captured','failed','partially_refunded','refunded');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', phone text, role public.app_role not null default 'customer', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.vendors (id uuid primary key default gen_random_uuid(), owner_id uuid not null unique references public.profiles(id), store_name text not null, slug text not null unique, description text not null default '', status public.vendor_status not null default 'pending', commission_bps integer not null default 1000 check (commission_bps between 0 and 5000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), parent_id uuid references public.categories(id), name text not null, slug text not null unique, image_url text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), category_id uuid not null references public.categories(id), title text not null, slug text not null, description text not null default '', sku text not null, price_paise bigint not null check (price_paise >= 0), compare_at_price_paise bigint check (compare_at_price_paise is null or compare_at_price_paise >= price_paise), currency char(3) not null default 'INR' check (currency = 'INR'), stock_quantity integer not null default 0 check (stock_quantity >= 0), status public.product_status not null default 'draft', attributes jsonb not null default '{}'::jsonb, images jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(vendor_id, slug), unique(vendor_id, sku));
create index products_browse_idx on public.products(status, category_id, created_at desc) where status = 'published';
create index products_vendor_idx on public.products(vendor_id, status);
create index products_search_idx on public.products using gin (to_tsvector('simple', coalesce(title,'') || ' ' || coalesce(description,'')));
create table public.addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, label text not null default 'Home', recipient_name text not null, phone text not null, line1 text not null, line2 text, city text not null, state text not null, postal_code text not null, country_code char(2) not null default 'IN', is_default boolean not null default false, created_at timestamptz not null default now());
create index addresses_user_idx on public.addresses(user_id);
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text not null unique, customer_id uuid not null references public.profiles(id), status public.order_status not null default 'pending_payment', currency char(3) not null default 'INR' check (currency='INR'), subtotal_paise bigint not null check (subtotal_paise >= 0), shipping_paise bigint not null default 0 check (shipping_paise >= 0), tax_paise bigint not null default 0 check (tax_paise >= 0), discount_paise bigint not null default 0 check (discount_paise >= 0), total_paise bigint not null check (total_paise >= 0), shipping_address_snapshot jsonb not null, placed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index orders_customer_idx on public.orders(customer_id, created_at desc);
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete restrict, vendor_id uuid not null references public.vendors(id), product_id uuid references public.products(id) on delete set null, product_snapshot jsonb not null, sku_snapshot text not null, quantity integer not null check (quantity > 0), unit_price_paise bigint not null check (unit_price_paise >= 0), commission_paise bigint not null default 0 check (commission_paise >= 0), tax_paise bigint not null default 0 check (tax_paise >= 0), created_at timestamptz not null default now());
create index order_items_vendor_idx on public.order_items(vendor_id, created_at desc);
create table public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete restrict, provider text not null, provider_order_id text unique, provider_payment_id text unique, status public.payment_status not null default 'created', amount_paise bigint not null check (amount_paise >= 0), currency char(3) not null default 'INR', idempotency_key text not null unique, webhook_event_id text unique, failure_code text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.shipments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete restrict, vendor_id uuid not null references public.vendors(id), provider text, provider_shipment_id text, tracking_number text, status text not null default 'unfulfilled', tracking_url text, shipped_at timestamptz, delivered_at timestamptz, created_at timestamptz not null default now(), unique(provider, provider_shipment_id));
create table public.refunds (id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.payments(id), order_item_id uuid references public.order_items(id), amount_paise bigint not null check (amount_paise > 0), reason text not null, status text not null default 'pending', provider_refund_id text unique, requested_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reviews (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, customer_id uuid not null references public.profiles(id), order_item_id uuid references public.order_items(id), rating smallint not null check (rating between 1 and 5), title text, body text not null default '', is_published boolean not null default false, created_at timestamptz not null default now(), unique(customer_id, order_item_id));
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'::public.app_role) $$;
create or replace function public.owns_vendor(target_vendor uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.vendors where id=target_vendor and owner_id=auth.uid()) $$;
create or replace function public.customer_owns_order(target_order uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.orders where id=target_order and customer_id=auth.uid()) $$;
create or replace function public.vendor_has_order(target_order uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.order_items oi join public.vendors v on v.id=oi.vendor_id where oi.order_id=target_order and v.owner_id=auth.uid()) $$;
create or replace function public.guard_profile_role_change() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if new.role is distinct from old.role and not public.is_admin() then raise exception 'role changes require an administrator'; end if; return new; end; $$;
create trigger profiles_prevent_role_escalation before update on public.profiles for each row execute function public.guard_profile_role_change();
alter table public.profiles enable row level security; alter table public.vendors enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.shipments enable row level security; alter table public.refunds enable row level security; alter table public.reviews enable row level security; alter table public.audit_logs enable row level security;
create policy "profiles read self or admin" on public.profiles for select using (id=auth.uid() or public.is_admin());
create policy "profiles update self" on public.profiles for update using (id=auth.uid()) with check (id=auth.uid());
create policy "approved vendors are public" on public.vendors for select using (status='approved' or owner_id=auth.uid() or public.is_admin());
create policy "vendor owner may create own vendor application" on public.vendors for insert with check (owner_id=auth.uid() and status='pending');
create policy "vendor owner may update own vendor details" on public.vendors for update using (owner_id=auth.uid() or public.is_admin()) with check (owner_id=auth.uid() or public.is_admin());
create policy "active categories are public" on public.categories for select using (is_active or public.is_admin());
create policy "published products are public" on public.products for select using (status='published' or public.owns_vendor(vendor_id) or public.is_admin());
create policy "vendor can create draft products" on public.products for insert with check (public.owns_vendor(vendor_id) and status in ('draft','pending_review'));
create policy "vendor can update own products" on public.products for update using (public.owns_vendor(vendor_id) or public.is_admin()) with check (public.owns_vendor(vendor_id) or public.is_admin());
create policy "customer manages own addresses" on public.addresses for all using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin());
create policy "customer reads own orders" on public.orders for select using (customer_id=auth.uid() or public.is_admin());
create policy "vendor reads orders containing their items" on public.orders for select using (public.is_admin() or public.vendor_has_order(id));
create policy "customer reads own order items" on public.order_items for select using (public.is_admin() or public.customer_owns_order(order_id) or public.owns_vendor(vendor_id));
create policy "customer reads own payments" on public.payments for select using (public.is_admin() or public.customer_owns_order(order_id));
create policy "shipment parties read shipment" on public.shipments for select using (public.is_admin() or public.owns_vendor(vendor_id) or public.customer_owns_order(order_id));
create policy "customer reads own refunds" on public.refunds for select using (public.is_admin() or requested_by=auth.uid() or exists(select 1 from public.payments p where p.id=payment_id and public.customer_owns_order(p.order_id)));
create policy "published reviews are public" on public.reviews for select using (is_published or customer_id=auth.uid() or public.is_admin());
create policy "customer may submit own review" on public.reviews for insert with check (customer_id=auth.uid() and is_published=false);
create policy "audit logs admin only" on public.audit_logs for select using (public.is_admin());
-- Intentionally no client insert/update policies for orders, order_items, payments, refunds, shipments, or audit_logs.
-- Create these only through trusted server-side functions after validating inventory, current prices, authorization, payment signatures and idempotency.
